export const DIAGNOSIS_NAMES: string[] = ESV_ICD11_DIAGNOSES.map((d) => d.display);

export const DIAGNOSIS_CODE_MAP: Record<string, string> = {};
for (const d of ESV_ICD11_DIAGNOSES) {
  DIAGNOSIS_CODE_MAP[d.display.toLowerCase()] = d.code;
  DIAGNOSIS_CODE_MAP[d.name.toLowerCase()] = d.code;
  DIAGNOSIS_CODE_MAP[d.code.toLowerCase()] = d.code;
}

/**
 * High-frequency clinical diagnoses in outpatient & inpatient practice
 * for quick 1-click chip selection.
 */
export const COMMON_DIAGNOSES: string[] = [
  "Essential hypertension (BA00)",
  "Type 2 diabetes mellitus (5A11)",
  "Acute nasopharyngitis (CA00)",
  "Acute pharyngitis, unspecified (CA02.Z)",
  "Acute bronchitis (CA42)",
  "Pneumonia (CA40)",
  "Asthma (CA23)",
  "Gastroenteritis or colitis without specification of infectious agent (1A40)",
  "Typhoid fever (1A07)",
  "Malaria due to Plasmodium falciparum (1F40)",
  "Urinary tract infection, site not specified (GC08)",
  "Dyspepsia (MD92)",
  "Low back pain (ME84.2)",
  "Gastritis (DA42)",
  "Migraine (8A80)",
  "Conjunctivitis (9A60)",
];

const CUSTOM_DIAGNOSES_STORAGE_KEY = "healthcare_custom_diagnoses_v1";

function loadCustomDiagnoses(): DiagnosisEntry[] {
  try {
    const raw = localStorage.getItem(CUSTOM_DIAGNOSES_STORAGE_KEY);
    if (!raw) return [];
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

function saveCustomDiagnoses(items: DiagnosisEntry[]): void {
  try {
    localStorage.setItem(CUSTOM_DIAGNOSES_STORAGE_KEY, JSON.stringify(items));
  } catch {
    // Ignore storage quota errors
  }
}

// Hydrate stored custom diagnoses into current runtime catalog
const storedCustom = loadCustomDiagnoses();
for (const item of storedCustom) {
  const norm = item.display.toLowerCase();
  if (!DIAGNOSIS_NAMES.some((n) => n.toLowerCase() === norm)) {
    DIAGNOSIS_NAMES.push(item.display);
    ESV_ICD11_DIAGNOSES.push(item);
  }
  if (item.code) {
    DIAGNOSIS_CODE_MAP[norm] = item.code;
    DIAGNOSIS_CODE_MAP[item.name.toLowerCase()] = item.code;
    DIAGNOSIS_CODE_MAP[item.code.toLowerCase()] = item.code;
  }
}

export function registerCustomDiagnosis(name: string, code?: string): DiagnosisEntry {
  const trimmed = name.trim();
  const cleanCode = code?.trim() || "";
  const display = cleanCode ? `${trimmed} (${cleanCode})` : trimmed;

  const entry: DiagnosisEntry = {
    code: cleanCode,
    name: trimmed,
    display,
    chapter: "Custom / Local Diagnosis",
  };

  const key = display.toLowerCase();
  const existingIdx = DIAGNOSIS_NAMES.findIndex((n) => n.toLowerCase() === key);
  if (existingIdx === -1) {
    DIAGNOSIS_NAMES.push(display);
    ESV_ICD11_DIAGNOSES.push(entry);
  } else {
    DIAGNOSIS_NAMES[existingIdx] = display;
  }

  if (cleanCode) {
    DIAGNOSIS_CODE_MAP[key] = cleanCode;
    DIAGNOSIS_CODE_MAP[trimmed.toLowerCase()] = cleanCode;
    DIAGNOSIS_CODE_MAP[cleanCode.toLowerCase()] = cleanCode;
  }

  const current = loadCustomDiagnoses().filter((d) => d.display.toLowerCase() !== key);
  current.push(entry);
  saveCustomDiagnoses(current);

  return entry;
}

export function getCustomDiagnoses(): DiagnosisEntry[] {
  return loadCustomDiagnoses();
}

export function getDiagnosisCode(nameOrDisplay: string): string | undefined {
  if (!nameOrDisplay) return undefined;
  return DIAGNOSIS_CODE_MAP[nameOrDisplay.toLowerCase().trim()];
}
